import IP from 'ip-address';
import { Address4, Address6 } from 'ip-address';

export default (ip) => {
  try {
    // Try to parse as IPv4 first
    const ipv4 = new Address4(ip);
    if (ipv4.isValid()) {
      // Check if it's in private IPv4 ranges
      return ipv4.isInSubnet(new Address4('10.0.0.0/8')) ||
             ipv4.isInSubnet(new Address4('172.16.0.0/12')) ||
             ipv4.isInSubnet(new Address4('192.168.0.0/16')) ||
             ipv4.isInSubnet(new Address4('127.0.0.0/8')) ||
             ipv4.isInSubnet(new Address4('169.254.0.0/16')) ||
             ipv4.isInSubnet(new Address4('0.0.0.0/8')) ||
             ipv4.isInSubnet(new Address4('100.64.0.0/10')) ||
             // Loopback and other special ranges
             ipv4.address === '0.0.0.0' ||
             ipv4.address.startsWith('127.');
    }
  } catch (e) {
    // Not a valid IPv4, continue to check IPv6
  }

  try {
    // Try to parse as IPv6
    const ipv6 = new Address6(ip);
    if (ipv6.isValid()) {
      // Check if it's in private IPv6 ranges
      return ipv6.isInSubnet(new Address6('fc00::/7')) ||     // Unique Local Address (ULA)
             ipv6.isInSubnet(new Address6('fe80::/10')) ||    // Link-Local
             ipv6.isInSubnet(new Address6('::1/128')) ||     // Loopback
             ipv6.isInSubnet(new Address6('::/128')) ||      // Unspecified
             ipv6.isInSubnet(new Address6('2001:db8::/32')) || // Documentation
             ipv6.isInSubnet(new Address6('ff00::/8')) ||    // Multicast
             ipv6.isInSubnet(new Address6('100::/64')) ||    // Discard Prefix
             // IPv4-mapped IPv6 addresses
             (ipv6.is4() && new Address4(ipv6.address4).isInSubnet(new Address4('10.0.0.0/8'))) ||
             (ipv6.is4() && new Address4(ipv6.address4).isInSubnet(new Address4('172.16.0.0/12'))) ||
             (ipv6.is4() && new Address4(ipv6.address4).isInSubnet(new Address4('192.168.0.0/16'))) ||
             (ipv6.is4() && new Address4(ipv6.address4).isInSubnet(new Address4('127.0.0.0/8'))) ||
             (ipv6.is4() && new Address4(ipv6.address4).isInSubnet(new Address4('169.254.0.0/16')));
    }
  } catch (e) {
    // Not a valid IPv6 either
    return false;
  }

  return false;
};

