import { isIPv4, isIPv6, isPrivate as isPrivateIP } from 'net';

export default (ip) => {
  // Check if it's a valid IPv4 or IPv6 address
  if (isIPv4(ip) || isIPv6(ip)) {
    // Use built-in isPrivate method to check if IP is private/reserved
    return isPrivateIP(ip);
  }

  // If not a valid IP address, return false
  return false;
};

