	p = strings.ReplaceAll(p, "\\", "/")

	// Check for path traversal attempts using regex
	if matched, _ := regexp.MatchString(`(?:^|[\/])\.\.(?:[\/]|$)`, p); matched {
		return ""
	}

	// Also check for absolute paths (Unix-style)
	if strings.HasPrefix(p, "/") {
		return ""
	}

	// Clean the path normally
	cleaned := path.Clean("/" + p)

	// Trim leading slash as per original behavior
	return strings.TrimPrefix(cleaned, "/")
}

