func handleConnect(config *Config, pctx *goproxy.ProxyCtx) error {
	sctx := pctx.UserData.(*smokescreenContext)

	// Remove surrounding square brackets if present (but not for valid IPv6 addresses with ports)
	host := pctx.Req.Host
	if strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]") && !strings.Contains(host, ":]") {
		host = strings.TrimPrefix(strings.TrimSuffix(host, "]"), "[")
	}

	// Check if requesting role is allowed to talk to remote
	sctx.decision, sctx.lookupTime, pctx.Error = checkIfRequestShouldBeProxied(config, pctx.Req, host)
	if pctx.Error != nil {
		return pctx.Error
	}
	if !sctx.decision.allow {
		return denyError{errors.New(sctx.decision.reason)}
	}

	return nil
}

