func (hs *HTTPServer) getPluginAssets(c *models.ReqContext) {
	pluginID := web.Params(c.Req)[":pluginId"]

	// Validate pluginID doesn't contain path traversal characters
	if pluginID != filepath.Base(pluginID) {
		c.JsonApiErr(404, "Plugin not found", nil)
		return
	}

	plugin, exists := hs.pluginStore.Plugin(c.Req.Context(), pluginID)
	if !exists {
		c.JsonApiErr(404, "Plugin not found", nil)
		return
	}

	requestedFile := filepath.Clean(web.Params(c.Req)["*"])

	// Validate requestedFile doesn't attempt path traversal
	if strings.Contains(requestedFile, "..") {
		c.JsonApiErr(404, "Plugin file not found", nil)
		return
	}

	pluginFilePath := filepath.Join(plugin.PluginDir, requestedFile)

	// Ensure the final path is still within the plugin directory
	rel, err := filepath.Rel(plugin.PluginDir, pluginFilePath)
	if err != nil || strings.HasPrefix(rel, "..") || rel == ".." {
		c.JsonApiErr(404, "Plugin file not found", nil)
		return
	}

	if !plugin.IncludedInSignature(requestedFile) {
		hs.log.Warn("Access to requested plugin file will be forbidden in upcoming Grafana versions as the file "+
			"is not included in the plugin signature", "file", requestedFile)
	}

	// It's safe to ignore gosec warning G304 since we already clean the requested file path and subsequently
	// use this with a prefix of the plugin's directory, which is set during plugin loading
	// nolint:gosec
	f, err := os.Open(pluginFilePath)
	if err != nil {
		if os.IsNotExist(err) {
			c.JsonApiErr(404, "Plugin file not found", err)
			return
		}
		c.JsonApiErr(500, "Could not open plugin file", err)
		return
	}
	defer func() {
		if err := f.Close(); err != nil {
			hs.log.Error("Failed to close file", "err", err)
		}
	}()

	fi, err := f.Stat()
	if err != nil {
		c.JsonApiErr(500, "Plugin file exists but could not open", err)
		return
	}

	if hs.Cfg.Env == setting.Dev {
		c.Resp.Header().Set("Cache-Control", "max-age=0, must-revalidate, no-cache")
	} else {
		c.Resp.Header().Set("Cache-Control", "public, max-age=3600")
	}

	http.ServeContent(c.Resp, c.Req, pluginFilePath, fi.ModTime(), f)
}

