func isOriginAllowed(allows []string, origin string) bool {
	for _, o := range allows {
		if o == allOrigins {
			return true
		}

		// Parse the origin to get the host
		originURL, err := url.Parse(origin)
		if err != nil {
			continue
		}
		originHost := originURL.Host

		// Remove port from origin host if present
		if host, port, err := net.SplitHostPort(originHost); err == nil {
			originHost = host
		} else if err != nil && strings.Contains(err.Error(), "missing port in address") {
			originHost = host
		}

		// Parse allowed origin
		allowedURL, err := url.Parse(o)
		var allowedHost string
		if err != nil {
			// If parsing fails, assume o is a raw host
			allowedHost = o
		} else {
			allowedHost = allowedURL.Host
		}

		// Remove port from allowed host if present
		if host, port, err := net.SplitHostPort(allowedHost); err == nil {
			allowedHost = host
		} else if err != nil && strings.Contains(err.Error(), "missing port in address") {
			allowedHost = host
		}

		// Exact match comparison
		if originHost == allowedHost {
			return true
		}
	}

	return false
