	registered, err := url.Parse(registeredURI)
	if err != nil {
		return false
	}

	// Must be HTTP scheme and loopback address for registered URI
	if registered.Scheme != "http" || !isLoopbackAddress(registered.Host) {
		return false
	}

	// Requested URI must also be HTTP and loopback
	if requested.Scheme != "http" || !isLoopbackAddress(requested.Host) {
		return false
	}

	// Paths must match exactly
	if registered.Path != requested.Path {
		return false
	}

