	// - If registered has no query params, requested can add safe params
	// - If registered has query params, requested must contain all of them
	registeredParams, _ := url.ParseQuery(registered.RawQuery)
	requestedParams, _ := url.ParseQuery(requested.RawQuery)

	// Check if all registered parameters exist in requested with same values
	for key, regValues := range registeredParams {
		reqValues := requestedParams[key]
		if len(reqValues) != len(regValues) {
			return false
		}
		// Compare values (order-independent)
		regMap := make(map[string]int)
		for _, v := range regValues {
