				}
				current = filepath.Join(current, part)
				if target, ok := symlinks[current]; ok {
					// This directory is a symlink, check if it's safe
					targetPath := filepath.Join(filepath.Dir(current), target)
					rel, err := filepath.Rel(dst, targetPath)
					if err != nil || strings.HasPrefix(rel, "..") {
						return fmt.Errorf("Cannot extract %q through symlink", header.Name)
					}
				}
			}
		} else {
			// Successfully resolved, check if it's within dst
			rel, err := filepath.Rel(dst, resolvedDir)
			if err != nil || strings.HasPrefix(rel, "..") {
				return fmt.Errorf("Cannot extract %q through symlink", header.Name)
			}
		}

		// Open a handle to the destination.
		fh, err := os.Create(path)
		if err != nil {
			// This mimics tar's behavior wrt the tar file containing duplicate files
			// and it allowing later ones to clobber earlier ones even if the file
			// has perms that don't allow overwriting.
			if os.IsPermission(err) {
				os.Chmod(path, 0600)
				fh, err = os.Create(path)
			}

			if err != nil {
				return fmt.Errorf("Failed creating file %q: %v", path, err)
			}
		}

		// Copy the contents.
		_, err = io.Copy(fh, untar)
		fh.Close()
		if err != nil {
			return fmt.Errorf("Failed to copy slug file %q: %v", path, err)
		}

