function diskusage(path, cb) {
    // Validate input path
    if (typeof path !== 'string' || path.length === 0) {
        return cb(new Error('Path must be a non-empty string'));
    }

    // Check for common shell metacharacters that could lead to command injection
    const dangerousChars = /[;&|`$\n\r<>\(\)]/;
    if (dangerousChars.test(path)) {
        return cb(new Error('Path contains dangerous characters'));
    }

    // Use spawn instead of exec to avoid shell interpretation
    const child = spawn('df', ['-k', path]);

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', (data) => {
        stdout += data.toString();
    });

    child.stderr.on('data', (data) => {
        stderr += data.toString();
    });

    child.on('error', (err) => {
        cb(err);
    });

    child.on('close', (code) => {
        if (code !== 0) {
            return cb(new Error(`Command failed with exit code ${code}: ${stderr}`));
        }

        try {
            cb(null, parse(stdout));
        } catch (e) {
            cb(e);
        }
    });
}

