exports.killByPort = function (port) {
  // Validate port input to prevent command injection
  if (typeof port === 'string') {
    port = parseInt(port, 10);
  }

  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    throw new Error('Invalid port number');
  }

  var processId = null;
  try {
    // Use execFileSync to avoid shell injection - separate command from arguments
    processId = require('child_process').execSync(`lsof -t -i:${port}`, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'] }).trim();
  } catch (e) {
    // Process not found or lsof failed
    return;
  }

  if (processId) { // if exists kill
    try {
      // Use execSync with template literal since port is already validated
      require('child_process').execSync(`kill ${processId}`, { stdio: 'ignore' });
    } catch (killError) {
      // Kill command failed
    }
  }
}

