exports.killByPort = function (port) {
  // Validate port input to prevent command injection
  if (typeof port === 'string') {
    port = parseInt(port, 10);
  }

  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    throw new Error('Invalid port number');
  }

  var processId = null;
  try {
    // Use execFileSync to avoid shell injection
    processId = require('child_process').execFileSync('lsof', ['-t', `-i:${port}`], { 
      encoding: 'utf8', 
      stdio: ['pipe', 'pipe', 'ignore'] 
    }).trim();
  } catch (e) {
    // Process not found or lsof failed
    return;
  }

  if (processId) { // if exists kill
    try {
      // Validate processId to prevent command injection
      if (!/^[0-9]+$/.test(processId)) {
        throw new Error('Invalid process ID');
      }
      // Use execFileSync to avoid shell injection
      require('child_process').execFileSync('kill', [processId], { stdio: 'ignore' });
    } catch (killError) {
      // Kill command failed
    }
  }
}

