module.exports = function (packageName, { registry = '', timeout = null } = {}) {
    try {
        // Validate package name
        if (!packageName || typeof packageName !== 'string' || !/^[a-zA-Z0-9@/_\-.]+$/.test(packageName)) {
            return null;
        }

        // Validate registry if provided
        if (registry && typeof registry === 'string') {
            try {
                new URL(registry);
            } catch (urlError) {
                return null;
            }
        }

        let version;
        const spawnSync = require('child_process').spawnSync;

        const config = {
            stdio: ['pipe', 'pipe', 'ignore'],
            encoding: 'utf-8'
        };

        if (timeout) {
            config.timeout = timeout;
        }

        if (registry) {
            const result = spawnSync('npm', ['view', packageName, 'version', '--registry', registry], config);
            if (result.error || result.status !== 0) {
                return null;
            }
            version = result.stdout;
        } else {
            const result = spawnSync('npm', ['view', packageName, 'version'], config);
            if (result.error || result.status !== 0) {
                return null;
            }
            version = result.stdout;
        }

        if (version) {
            return version.toString().trim().replace(/^\n*/, '').replace(/\n*$/, '');
        } else {
            return null;
        }

    } catch(err) {
        return null;
    }
}

