ImageProto.stream = function(type, writer) {

	var self = this;

	!self.builder.length && self.minify();

	if (!type)
		type = self.outputType;

	// Normalize and sanitize the type parameter to prevent command injection
	var allowedTypes = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'tiff', 'svg'];
	var cleanType = (type || '').toString().toLowerCase().replace(/[^a-z0-9]/g, '');

	// If the cleaned type is not in our allowed list, default to a safe value like 'png'
	if (cleanType && allowedTypes.indexOf(cleanType) === -1) {
		cleanType = 'png'; // Default to a safe fallback instead of throwing an error
