	F.stats.performance.open++;
	// Remove shell: true from SPAWN_OPT to prevent shell interpretation
	var cmdOptions = Object.assign({}, SPAWN_OPT);
	delete cmdOptions.shell;
	var cmd = spawn(CMD_CONVERT[self.cmdarg], self.arg(self.filename ? wrap(self.filename) : '-', (cleanType ? cleanType + ':' : '') + '-'), cmdOptions);
