trimvideo: (input, start, duration, output) => {
  return new Promise(function(resolve, reject) {
    // Validate input parameters
    if (typeof start !== 'string' || typeof duration !== 'string' || typeof output !== 'string') {
      reject(new Error('Invalid parameter types'));
      return;
    }

    // Validate time format (HH:MM:SS or seconds)
    const timeFormat = /^([0-9]+:){0,2}[0-9]+([.,][0-9]+)?$/;
    if (!timeFormat.test(start) || !timeFormat.test(duration)) {
      reject(new Error('Invalid time format for start or duration'));
      return;
    }

    // Sanitize output filename - allow alphanumeric, dash, underscore, dot only
    const filenameFormat = /^[a-zA-Z0-9._-]+$/;
    if (!filenameFormat.test(output)) {
      reject(new Error('Invalid output filename format'));
      return;
    }

    // Validate input file exists
    if (fs.existsSync(input)) {
      // Use spawn instead of exec for better security
      const { spawn } = require('child_process');

      // Construct arguments array to avoid shell interpretation
      const args = [
        '-hide_banner',
        '-loglevel', 'quiet',
        '-ss', start,
        '-i', input,
        '-t', duration,
        '-c', 'copy',
        '-y', `${output}.mp4`
      ];

      const ffmpegProcess = spawn('ffmpeg', args);

      let stdout = '';
      let stderr = '';

      ffmpegProcess.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      ffmpegProcess.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      ffmpegProcess.on('error', (error) => {
        reject(error);
      });

      ffmpegProcess.on('close', (code) => {
        if (code !== 0) {
          reject(new Error(`FFmpeg exited with code ${code}: ${stderr}`));
        } else {
          resolve(`${output}.mp4`);
        }
      });
    } else {
      reject(new Error("ffmpegdotjs could not find file"));
    }
  });
},

