patch:
var cleanUrl = function(url, rootPath) { 
	try {
		// Decode the URL first
		url = decodeURIComponent(url);

		// Resolve the full path
		var fullPath = require('path').resolve(rootPath, url);

		// Check if the resolved path is within the root directory
		var rootPathResolved = require('path').resolve(rootPath);

		// Return whether the path is safe (within root)
		return fullPath.indexOf(rootPathResolved) === 0;
	} catch (e) {
		// If any error occurs during path resolution, consider it unsafe
		return false;
	}
};

