// isValidSortKey validates that the sort key contains only safe characters
// allowing alphanumeric, underscore, and dot characters commonly used in column names
func isValidSortKey(key string) bool {
	matched, err := regexp.MatchString(`^[a-zA-Z0-9_.]+$`, key)
	return err == nil && matched
}

