func UntarToDirectory(reader io.Reader, dst string) error {
	visitor := func(entry TarFileEntry) error {
		// Check for illegal patterns in the raw header name
		if strings.Contains(entry.Header.Name, "..") {
			return fmt.Errorf("illegal file path in tar: %v", entry.Header.Name)
		}

		// Construct and sanitize the full target path
		target := filepath.Join(dst, entry.Header.Name)
		cleanTarget := filepath.Clean(target)

		// Prevent path traversal outside of dst directory
		relPath, err := filepath.Rel(dst, cleanTarget)
		if err != nil || strings.HasPrefix(relPath, "..") || relPath == ".." {
			return fmt.Errorf("illegal file path in tar: %v", entry.Header.Name)
		}

		switch entry.Header.Typeflag {
		case tar.TypeDir:
			if _, err := os.Stat(cleanTarget); err != nil {
				if err := os.MkdirAll(cleanTarget, 0755); err != nil {
					return err
				}
			}

		case tar.TypeReg:
			f, err := os.OpenFile(cleanTarget, os.O_CREATE|os.O_RDWR, os.FileMode(entry.Header.Mode))
			if err != nil {
				return err
			}

			// limit the reader on each file read to prevent decompression bomb attacks
			numBytes, err := io.Copy(f, io.LimitReader(entry.Reader, perFileReadLimit))
			if numBytes >= perFileReadLimit || errors.Is(err, io.EOF) {
				return fmt.Errorf("zip read limit hit (potential decompression bomb attack)")
			}
			if err != nil {
				return fmt.Errorf("unable to copy file: %w", err)
			}

			if err = f.Close(); err != nil {
				log.Errorf("failed to close file during untar of path=%q: %w", f.Name(), err)
			}
		}
		return nil
	}

	return IterateTar(reader, visitor)
}

