func PDFHasImage(path string) bool {
	// Validate that path is not empty and does not contain shell metacharacters
	if path == "" {
		return false
	}

	// Use exec.Command with separate arguments to avoid shell injection
	cmd := exec.Command("pdffonts", "-l", "5", path)
	out, err := cmd.Output()
	if err != nil {
		log.Println(err)
		return false
	}

	// Process the output with separate commands
	lines := strings.Split(strings.TrimSpace(string(out)), "\n")
	if len(lines) < 3 {
		return true
	}

	// Equivalent to tail -n +3 | cut -d' ' -f1 | sort | uniq
	fields := make([]string, 0)
	for i := 2; i < len(lines); i++ {
		line := strings.TrimSpace(lines[i])
		if line != "" {
			parts := strings.Fields(line)
			if len(parts) > 0 {
				fields = append(fields, parts[0])
			}
		}
	}

	if len(fields) == 0 {
		return true
	}
	return false
}

