def _extract_packages_archive(work_dir):
    package_file = os.path.join(work_dir, "packages.tar")
    if not os.path.exists(package_file):
        return

    curdir = os.path.abspath(os.curdir)

    os.chdir(work_dir)
    tar = tarfile.open(package_file)
    for tarinfo in tar:
        # Security fix: Prevent Zip Slip vulnerability
        extracted_path = os.path.normpath(os.path.join(work_dir, tarinfo.name))
        if extracted_path.startswith(os.path.join(work_dir, '')):
            tar.extract(tarinfo, work_dir)
    tar.close()
    if '' not in sys.path:
        sys.path.insert(0, '')

    os.chdir(curdir)

