// isValidPrefix checks if the prefix is safe to use in a URL path
func isValidPrefix(prefix string) bool {
	// Check for empty prefix
	if prefix == "" {
		return false
	}

	// Check for invalid characters in prefix
	for _, r := range prefix {
		// Allow alphanumeric characters, hyphens, underscores, slashes, and dots
		if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == '-' || r == '_' || r == '/' || r == '.') {
			return false
		}
	}

	// Prevent prefix from containing dangerous patterns
	if strings.Contains(prefix, "..") || strings.HasPrefix(prefix, "//") {
		return false
	}

	return true
}

