func redirectTrailingSlash(c *Context) {
	req := c.Request
	p := req.URL.Path
	if prefix := c.Request.Header.Get("X-Forwarded-Prefix"); prefix != "" {
		// Validate prefix: must be absolute path, no dot-dot sequences, no embedded nulls
		if len(prefix) > 0 && prefix[0] == '/' {
			cleanPrefix := path.Clean(prefix)
			if cleanPrefix != "." && cleanPrefix != "/" && !strings.Contains(cleanPrefix, "..") {
				p = path.Join(cleanPrefix, p)
			}
		}
	}
	p = path.Clean(p)
	if !strings.HasSuffix(p, "/") {
		req.URL.Path = p + "/"
	} else {
		req.URL.Path = p
	}
	redirectRequest(c)
}

