function isValidWebFingerHost(host: string): boolean {
  // Remove brackets for IPv6 addresses
  const cleanHost = host.replace(/^\[(.*)\]$/, '$1');

  // Block localhost and loopback addresses
  if (cleanHost === 'localhost' || 
      cleanHost === 'localhost.' ||
      cleanHost.match(/^(127\.0\.0\.1|\[::1\]|::1)(:\d+)?$/)) {
    return false;
  }

  // Block private IP ranges
  try {
    // For IPv4 addresses
    if (cleanHost.match(/^\d+\.\d+\.\d+\.\d+/)) {
      const parts = cleanHost.split('.');
      if (parts.length >= 4) {
        const firstOctet = parseInt(parts[0]);
        const secondOctet = parseInt(parts[1]);

        // 10.x.x.x
        if (firstOctet === 10) return false;
        // 172.16.x.x - 172.31.x.x
        if (firstOctet === 172 && secondOctet >= 16 && secondOctet <= 31) return false;
        // 192.168.x.x
        if (firstOctet === 192 && secondOctet === 168) return false;
      }
    }

    // For IPv6 addresses, check if they are loopback or link-local
    if (cleanHost.includes(':')) {
      // Check for IPv6 loopback (::1) or link-local (fe80::)
      if (cleanHost.startsWith('fe80::') || cleanHost === '::1') {
        return false;
      }
    }
  } catch (e) {
    // If we can't parse it, be conservative and allow it
    // The fetch will fail anyway if it's truly invalid
  }

  return true;
}

