getInfo: function () {
  var self = this;
  var commandInfo = this.constructGetInfoCommand();
  var promise = new Promise(function (resolve, reject) {
    // Use spawn instead of exec to avoid shell interpretation
    var child = spawn(commandInfo.command, commandInfo.args);
    var stdout = '';
    var stderr = '';

    child.stdout.on('data', function (data) {
      stdout += data;
    });

    child.stderr.on('data', function (data) {
      stderr += data;
    });

    child.on('error', function (err) {
      return reject({
        message: "Failed to get PDF'S information",
        error: err,
        stdout: stdout,
        stderr: stderr
      });
    });

    child.on('close', function (code) {
      if (code !== 0) {
        var err = new Error('Command failed with exit code ' + code);
        return reject({
          message: "Failed to get PDF'S information",
          error: err,
          stdout: stdout,
          stderr: stderr
        });
      }
      return resolve(self.parseGetInfoCommandOutput(stdout));
    });
  });
  return promise;
},

