    try {
      const urlObj = new URL(url, 'http://example.com');

      // If it's an absolute URL, validate the host
      if (urlObj.host && urlObj.host !== 'example.com') {
        const allowedHosts = this.app.get('allowedRedirectHosts') || [];

        // If allowedHosts is configured, check if host is allowed
        if (allowedHosts.length > 0) {
          if (!allowedHosts.includes(urlObj.host)) {
            // Block redirect to untrusted host
            loc = '/';
