function parseUrl(url, normalize = false) {
    if (typeof url !== "string" || !url.trim()) {
        throw new Error("Invalid url.")
    }

    // Validate normalize parameter
    if (typeof normalize !== "boolean" && typeof normalize !== "object") {
        throw new Error("Normalize parameter must be a boolean or an object.")
    }

    // Sanitize URL to remove sensitive information before processing
    let sanitizedUrl = url;

    // Remove potential auth tokens from URL
    sanitizedUrl = sanitizedUrl.replace(/[?&]token=[^&]*(&|$)/g, '$1');
    sanitizedUrl = sanitizedUrl.replace(/[?&]key=[^&]*(&|$)/g, '$1');
    sanitizedUrl = sanitizedUrl.replace(/[?&]password=[^&]*(&|$)/g, '$1');
    sanitizedUrl = sanitizedUrl.replace(/[?&]secret=[^&]*(&|$)/g, '$1');

    if (normalize) {
        if (typeof normalize !== "object") {
            normalize = {
                stripHash: false
            }
        }
        sanitizedUrl = normalizeUrl(sanitizedUrl, normalize)
    }

    const parsed = parsePath(sanitizedUrl)

    // Additional sanitization of parsed result
    if (parsed.query && typeof parsed.query === 'object') {
        delete parsed.query.token;
        delete parsed.query.key;
        delete parsed.query.password;
        delete parsed.query.secret;
    }

    return parsed;
}

