import (
	"fmt"
	"net"
	"strings"
)

// isInvalidExternalName checks if an ExternalName points to internal/privileged resources
func isInvalidExternalName(externalName string) bool {
	// Check for empty or obviously invalid names
	if externalName == "" {
		return true
	}

	// Check for localhost references
	if externalName == "localhost" || strings.HasPrefix(externalName, "localhost.") {
		return true
	}

	// Parse the hostname to check for IP addresses
	if ip := net.ParseIP(externalName); ip != nil {
		// Block localhost IPs
		if ip.IsLoopback() {
			return true
		}
		// Block private IP ranges (RFC 1918)
		if ip.IsPrivate() {
			return true
		}
		// Block link-local addresses
		if ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
			return true
		}
		// Block unspecified addresses
		if ip.IsUnspecified() {
			return true
		}
	} else {
		// For hostnames, check if they resolve to problematic IPs
		addrs, err := net.LookupHost(externalName)
		if err != nil {
			// If we can't resolve it, be conservative and block it
			return true
		}
		for _, addr := range addrs {
			ip := net.ParseIP(addr)
			if ip != nil {
				if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
					return true
				}
			}
		}
	}

	return false
}

