func matchSignatures(signatures []oci.Signature, subject, subjectRegExp, issuer, issuerRegExp string, extensions map[string]string) error {
	if subject == "" && subjectRegExp == "" && issuer == "" && issuerRegExp == "" && len(extensions) == 0 {
		return nil
	}

	var subjectRegexp *regexp.Regexp
	var issuerRegexp *regexp.Regexp
	var err error

	if subjectRegExp != "" {
		subjectRegexp, err = regexp.Compile(subjectRegExp)
		if err != nil {
			return fmt.Errorf("failed to compile subject regexp: %w", err)
		}
	}

	if issuerRegExp != "" {
		issuerRegexp, err = regexp.Compile(issuerRegExp)
		if err != nil {
			return fmt.Errorf("failed to compile issuer regexp: %w", err)
		}
	}

	var errs []error
	for _, sig := range signatures {
		cert, err := sig.Cert()
		if err != nil {
			return fmt.Errorf("failed to read certificate: %w", err)
		}

		if cert == nil {
			return fmt.Errorf("certificate not found")
		}

		if err := matchCertificateData(cert, subject, subjectRegExp, issuer, issuerRegExp, extensions, subjectRegexp, issuerRegexp); err != nil {
			errs = append(errs, err)
		} else {
			// only one signature certificate needs to match the required subject, issuer, and extensions
			return nil
		}
	}

	if len(errs) > 0 {
		err := multierr.Combine(errs...)
		return err
	}

	return fmt.Errorf("invalid signature")
}

