	funcMap["fail"] = func(msg string) (string, error) {
		if e.LintMode {
			// Don't fail when linting
			log.Printf("[INFO] Fail: %s", msg)
			return "", nil
		}
		return "", errors.New(warnWrap(msg))
	}

	// If we are not linting and have a cluster connection, provide a Kubernetes-backed
	// implementation.
	if !e.LintMode && e.config != nil {
		funcMap["lookup"] = NewLookupFunction(e.config)
	}

	// Handle getHostByName based on DisableNet setting to prevent DNS leakage
	// See CVE description: getHostByName performs DNS lookups that can leak information
	if e.DisableNet {
		// Override getHostByName to prevent actual DNS lookup
		funcMap["getHostByName"] = func(name string) (string, error) {
			// Return empty string or an error to indicate network access is disabled
			return "", errors.New("network access is disabled, getHostByName is not allowed")
		}
	}

	t.Funcs(funcMap)
}

