module.exports = path => {
  let r = ''
  while (isAbsolute(path)) {
    // windows will think that //x/y/z has a "root" of //x/y/
    const root = path.charAt(0) === '/' ? '/' : parse(path).root
    path = path.substr(root.length)
    r += root

    // Additional sanitization for Windows paths with drive letters
    // Check for paths like C:../foo or C:some\path that could escape target directory
    if (process.platform === 'win32') {
      // Handle drive letter paths that don't match current root
      if (/^[a-zA-Z]:\.*/.test(path)) {
        const driveLetter = path.charAt(0).toUpperCase()
        const currentDrive = root.charAt(0).toUpperCase()
        // If drive letters don't match, treat as relative path
        if (driveLetter !== currentDrive) {
          path = path.substr(2) // Remove drive letter and colon
        }
      }

      // Sanitize .. sequences that occur immediately after drive letter
      path = path.replace(/^([a-zA-Z]:)(\.{2,})([\\/]|$)/, '$1$3')

      // Normalize path to resolve any remaining relative components
      path = require('path').normalize(path)

      // Ensure path doesn't start with .. after normalization
      if (path.startsWith('..')) {
        path = path.substring(2)
        if (path.startsWith('/') || path.startsWith('\\')) {
          path = path.substring(1)
        }
      }
    }
  }
  return [r, path]
}

