	tk, ok := rc.contextualTuples.ReadUserTuple(rc.tk)
	if ok {
		// Check if an authorizer is available in the context
		if authorizer, ok := ctx.Value("authorizer").(interface{ Authorize(context.Context, *openfgapb.TupleKey) error }); ok {
			if err := authorizer.Authorize(ctx, tk); err != nil {
				return nil, err
			}
		}

		return tk, nil
	}

	tuple, err := backend.ReadUserTuple(ctx, rc.store, rc.tk)
	if err != nil {
		return nil, err
	}
	return tuple.GetKey(), nil
}

