func (a *AuthenticatorOAuth2Introspection) tokenFromCache(config *AuthenticatorOAuth2IntrospectionConfiguration, token string) (*AuthenticatorOAuth2IntrospectionResult, bool) {
	if !config.Cache.Enabled {
		return nil, false
	}

	// Create cache key that includes scopes to prevent scope bypass
	cacheKey := token
	if len(config.Scopes) > 0 {
		// Sort scopes for consistent cache key generation
		sortedScopes := make([]string, len(config.Scopes))
		copy(sortedScopes, config.Scopes)
		// Manual sort to avoid import issues
		for i := 0; i < len(sortedScopes); i++ {
			for j := i + 1; j < len(sortedScopes); j++ {
				if sortedScopes[i] > sortedScopes[j] {
					sortedScopes[i], sortedScopes[j] = sortedScopes[j], sortedScopes[i]
				}
			}
		}
		cacheKey = fmt.Sprintf("%s|%s", token, strings.Join(sortedScopes, ","))
	}

	item, found := a.tokenCache.Get(cacheKey)
	if !found {
		return nil, false
	}

	i := item.(*AuthenticatorOAuth2IntrospectionResult)
	expires := time.Unix(i.Expires, 0)
	if expires.Before(time.Now()) {
		a.tokenCache.Del(cacheKey)
		return nil, false
	}

	// Validate that cached token has required scopes
	tokenScopes := strings.Split(i.Scope, " ")
	ss := a.c.ToScopeStrategy(config.ScopeStrategy, "authenticators.oauth2_introspection.scope_strategy")
	if ss != nil {
		for _, requiredScope := range config.Scopes {
			if !ss(tokenScopes, requiredScope) {
				// Required scope not present, force re-introspection
				a.tokenCache.Del(cacheKey)
				return nil, false
			}
		}
	}

	return i, true
}

