        normalized_path = pathlib.Path(path).resolve(strict=False)
        # Convert to relative path to remove any leading slashes
        normalized_path = normalized_path.relative_to(normalized_path.anchor)
    except (OSError, ValueError):
        # Invalid path, return empty result
        return "", None

    for directory in self.all_directories:
        try:
            directory_path = pathlib.Path(directory).resolve()
            full_path = directory_path / normalized_path

            # Check if the full path is within the allowed directory
            if not full_path.is_relative_to(directory_path):
                continue

            # Resolve the full path to handle symlinks
            if self.follow_symlink:
                full_path = full_path.resolve()
            else:
                # For realpath, we need to check each component manually
                full_path = full_path.resolve(strict=False)
                if not full_path.is_relative_to(directory_path):
                    continue

            # Verify the file exists and get its stat
