    A method to clean the code to prevent malicious code execution

    Args:
        code(str): A python code

    Returns (str): Returns a Clean Code String

    """

    # Define safe node types
    safe_nodes = {
        ast.Module, ast.Expr, ast.Assign, ast.AugAssign, ast.AnnAssign,
        ast.Name, ast.Load, ast.Store, ast.Del, ast.Starred, ast.Attribute,
        ast.Subscript, ast.List, ast.Tuple, ast.Set, ast.Dict,
        ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp,
        ast.comprehension, ast.IfExp, ast.Call, ast.keyword,
        ast.Constant, ast.Num, ast.Str, ast.Bytes, ast.NameConstant, ast.Ellipsis,
        ast.UnaryOp, ast.BinOp, ast.BoolOp, ast.Compare,
        ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow,
        ast.LShift, ast.RShift, ast.BitOr, ast.BitXor, ast.BitAnd, ast.MatMult,
        ast.UAdd, ast.USub, ast.Not, ast.Invert,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Is, ast.IsNot, ast.In, ast.NotIn,
        ast.And, ast.Or,
        ast.FormattedValue, ast.JoinedStr,
        ast.Return, ast.If, ast.For, ast.While, ast.Break, ast.Continue, ast.Pass,
        ast.Try, ast.ExceptHandler, ast.With, ast.withitem,
        ast.FunctionDef, ast.Lambda, ast.arguments, ast.arg, ast.Kwargs, ast.Posonlyargs,
        ast.Slice, ast.ExtSlice, ast.Index
    }

    # Define safe function names that can be called
    safe_functions = {
        'print', 'len', 'range', 'enumerate', 'zip', 'map', 'filter',
        'sum', 'min', 'max', 'abs', 'round', 'pow', 'sorted',
        'str', 'int', 'float', 'bool', 'list', 'dict', 'set', 'tuple',
        'getattr', 'hasattr', 'isinstance', 'issubclass',
        # Add pandas/dataframe related safe functions
        'pd', 'df', 'DataFrame', 'read_csv', 'read_json', 'read_excel'
    }

    def is_safe_node(node):
        """Check if a node and all its children are safe"""
        if type(node) not in safe_nodes:
            return False

        # Additional checks for specific node types
        if isinstance(node, ast.Call):
            # Check function calls
            if isinstance(node.func, ast.Name):
                if node.func.id not in safe_functions:
                    # Allow attribute access on safe objects
                    if not (node.func.id.startswith('df') or node.func.id.startswith('pd')):
                        return False
            elif isinstance(node.func, ast.Attribute):
                # Check attribute access chain
                if not is_safe_attribute_access(node.func):
                    return False

        # Recursively check all child nodes
        for child in ast.iter_child_nodes(node):
            if not is_safe_node(child):
                return False
        return True

    def is_safe_attribute_access(node):
        """Check if attribute access is safe"""
        if isinstance(node, ast.Name):
            # Allow access to df and pd objects
            return node.id in ['df', 'pd', 'DataFrame']
        elif isinstance(node, ast.Attribute):
            # Recursively check the base object
            return is_safe_attribute_access(node.value)
        return False

    try:
        tree = ast.parse(code)
    except SyntaxError:
        raise ValueError("Invalid Python syntax in code")

    new_body = []

    # clear recent optional dependencies
    self._additional_dependencies = []

    for node in tree.body:
        # Remove imports and DataFrame overwrites as before
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            self._check_imports(node)
            continue
        if self._is_df_overwrite(node):
            continue

        # Check if the node is safe
        if not is_safe_node(node):
            raise ValueError("Unsafe code detected")

        new_body.append(node)

    new_tree = ast.Module(body=new_body)
    return astor.to_source(new_tree, pretty_source=lambda x: "".join(x)).strip()

