var BAD_PROTOCOLS    = [ 'vbscript', 'javascript', 'file' ];

function validateLink(url) {
  // url should be normalized at this point, and existing entities are decoded
  //
  var str = url.trim().toLowerCase();

  // Check for bad protocols
  if (str.indexOf(':') >= 0) {
    var protocol = str.split(':')[0];
    if (BAD_PROTOCOLS.indexOf(protocol) >= 0) {
      return false;
    }

    // Special handling for data URLs - only allow image MIME types
    if (protocol === 'data') {
      var mimeMatch = str.match(/^data:([^,;]+)/);
      if (mimeMatch && mimeMatch[1]) {
        var mimeType = mimeMatch[1];
        // Only allow image data URLs
        if (mimeType.indexOf('image/') !== 0) {
          return false;
        }
      } else {
        // Malformed data URL
        return false;
      }
    }
  }
  return true;
}

