func Init(ds model.DataStore) {
	once.Do(func() {
		log.Info("Setting Session Timeout", "value", conf.Server.SessionTimeout)
		secret, err := ds.Property(context.TODO()).Get(consts.JWTSecretKey)
		if err != nil || secret == "" {
			log.Error("No JWT secret found in DB. Setting a temp one, but please report this error", err)
			secret = uuid.NewString()
			// Encrypt the new secret before storing
			encryptedSecret, err := encryptSecret(secret)
			if err != nil {
				log.Error("Failed to encrypt JWT secret", err)
				// Fall back to plaintext if encryption fails
				encryptedSecret = secret
			}
			err = ds.Property(context.TODO()).Put(consts.JWTSecretKey, encryptedSecret)
			if err != nil {
				log.Error("Failed to store JWT secret in DB", err)
			}
			Secret = []byte(secret)
		} else {
			// Try to decrypt the secret, if it fails assume it's plaintext (backward compatibility)
			decryptedSecret, err := decryptSecret(secret)
			if err != nil {
				log.Warn("Failed to decrypt JWT secret, assuming plaintext", err)
				decryptedSecret = secret
			}
			Secret = []byte(decryptedSecret)
		}
		TokenAuth = jwtauth.New("HS256", Secret, nil)
	})
}

// encryptSecret encrypts the JWT secret using AES-GCM
func encryptSecret(plaintext string) (string, error) {
	// Generate a new encryption key (in production, this should be stored securely)
	key := make([]byte, 32) // 256 bits
	if _, err := rand.Read(key); err != nil {
		return "", err
	}

	block, err := aes.NewCipher(key)
	if err != nil {
		return "", err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return "", err
	}

	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return "", err
	}

	ciphertext := gcm.Seal(nonce, nonce, []byte(plaintext), nil)
	encodedKey := base64.StdEncoding.EncodeToString(key)
	encodedData := base64.StdEncoding.EncodeToString(ciphertext)

	// In a real implementation, the key should be stored securely (e.g., in environment variables or a key management service)
	// For this example, we're returning a combined string, but in practice you'd store the key separately
	return fmt.Sprintf("enc:%s:%s", encodedKey, encodedData), nil
}

// decryptSecret decrypts the JWT secret using AES-GCM
func decryptSecret(encryptedData string) (string, error) {
	parts := strings.Split(encryptedData, ":")
	if len(parts) != 3 || parts[0] != "enc" {
		return "", fmt.Errorf("invalid encrypted data format")
	}

	key, err := base64.StdEncoding.DecodeString(parts[1])
	if err != nil {
		return "", err
	}

	data, err := base64.StdEncoding.DecodeString(parts[2])
	if err != nil {
		return "", err
	}

	block, err := aes.NewCipher(key)
	if err != nil {
		return "", err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return "", err
	}

	if len(data) < gcm.NonceSize() {
		return "", fmt.Errorf("ciphertext too short")
	}

	nonce, ciphertext := data[:gcm.NonceSize()], data[gcm.NonceSize():]
	plaintext, err := gcm.Open(nil, nonce, ciphertext, nil)
	if err != nil {
		return "", err
	}

	return string(plaintext), nil
}

