		canonicalUsername := bodyJSON.Username
		if strings.Contains(bodyJSON.Username, "@") {
			// Input appears to be an email, resolve to username
			if user, err := ctx.Providers.UserProvider.GetDetails(bodyJSON.Username); err == nil && len(user.Username) > 0 {
				canonicalUsername = user.Username
			} else {
				ctx.Logger.Debugf("Unable to resolve email '%s' to username for regulation", bodyJSON.Username)
			}
		}

