function cpOptsInData(data, opts) {
  _OPTS.forEach(function (p) {
    if (typeof data[p] != 'undefined') {
      // Disallow setting the root opt for includes via a passed data obj
      // Unsanitized, parameterized use of `render` could allow the
      // include directory to be reset, opening up the possibility of
      // remote code execution
      if (p == 'root') {
        return;
      }

      // Validate input options to prevent DoS and other security issues
      // Only allow specific types and values for known options
      switch(p) {
        case 'cache':
        case 'debug':
        case 'compileDebug':
        case 'strict':
          // Boolean options
          if (typeof data[p] === 'boolean') {
            opts[p] = data[p];
          }
          break;
        case 'client':
          // Client option should be boolean
          if (typeof data[p] === 'boolean') {
            opts[p] = data[p];
          }
          break;
        case 'filename':
        case 'delimiter':
          // String options with reasonable length limits
          if (typeof data[p] === 'string' && data[p].length <= 1000) {
            opts[p] = data[p];
          }
          break;
        case 'context':
        case 'scope':
