    // Allows Unicode letters, $, _, and digits (but not as first character)
    if (!/^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(name)) {
      throw new Error('Invalid function name: must be a valid JavaScript identifier');
    }
    // Additional check to prevent reserved keywords
    var reserved = [
      'break', 'case', 'catch', 'continue', 'debugger', 'default', 'delete',
      'do', 'else', 'finally', 'for', 'function', 'if', 'in', 'instanceof',
      'new', 'return', 'switch', 'this', 'throw', 'try', 'typeof', 'var',
      'void', 'while', 'with', 'class', 'const', 'enum', 'export', 'extends',
      'import', 'super', 'implements', 'interface', 'let', 'package',
      'private', 'protected', 'public', 'static', 'yield'
    ];
    if (reserved.indexOf(name) !== -1) {
      throw new Error('Invalid function name: reserved keyword');
    }
  }

  // parse signatures, expand them
  var _signatures = parseSignatures(signatures);
  if (_signatures.length == 0) {
    throw new Error('No signatures provided');
  }

  // filter all any type signatures
