function buildURL (source, reqBase) {
  const dest = new URL(source, reqBase)

  // if base is specified, source url should not override it
  if (reqBase && !reqBase.startsWith(dest.origin)) {
    throw new Error('source must be a relative path string')
  }

  // Additional check to ensure the resolved path does not escape the base path
  if (reqBase) {
    const basePath = new URL(reqBase).pathname
    let destPath = dest.pathname

    // Normalize paths for comparison (remove trailing slashes except for root)
    const normalizedBase = basePath.endsWith('/') ? basePath.slice(0, -1) : basePath
    const normalizedDest = destPath.endsWith('/') ? destPath.slice(0, -1) : destPath

    // Ensure the destination path starts with the base path (or is the base path itself)
    if (!normalizedDest.startsWith(normalizedBase) &&
        !normalizedDest.startsWith(normalizedBase + '/')) {
      throw new Error('source must be within the base path')
    }
  }

  return dest
}

