  if (reqBase) {
    const basePath = new URL(reqBase).pathname
    const destPath = dest.pathname

    // Normalize paths by removing trailing slashes (except for root path)
    const normalizedBase = basePath === '/' ? '/' : basePath.replace(/\/+$/, '')
    const normalizedDest = destPath === '/' ? '/' : destPath.replace(/\/+$/, '')

