    if (normalizedBase !== '/') {
      if (!normalizedDest.startsWith(normalizedBase)) {
        throw new Error('source must be within the base path')
      }

      // Additional check to prevent path traversal after base path
      const suffix = normalizedDest.substring(normalizedBase.length)
      if (suffix && !suffix.startsWith('/')) {
        throw new Error('source must be within the base path')
      }
    } else {
      // For root base path, ensure no path traversal above root
      if (normalizedDest.includes('../') || normalizedDest.startsWith('..')) {
        throw new Error('source must be within the base path')
      }
    }
  }

  return dest
}

