  // Prevent homograph attacks by ensuring property names are ASCII-only
  // and don't disguise forbidden properties
  if (!/^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(key)) {
    return false;
  }

  // Block access to dangerous properties
  var forbidden = ['constructor', 'prototype', '__proto__'];
  if (forbidden.indexOf(key) !== -1) {
    return false;
  }

  return true;
}

function compileObjectNode(node, defs, args) {
  if (!(node instanceof ObjectNode)) {
    throw new TypeError('No valid ObjectNode')
  }

  var entries = [];
  for (var key in node.properties) {
    if (hasOwnProperty(node.properties, key)) {
      // Resolve unicode escapes early to detect disguised forbidden properties
      var resolvedKey = key.replace(/\\u([0-9a-fA-F]{4})/g, function(match, hex) {
        try {
          return String.fromCharCode(parseInt(hex, 16));
        } catch (e) {
          throw new Error('Invalid unicode escape in property name');
        }
      });

      // Validate the resolved key to prevent access to forbidden properties
      if (!isValidPropertyName(resolvedKey) || !isSafeProperty(node.properties, key)) {
        throw new Error('No access to property "' + resolvedKey + '"');
      }

      entries.push(stringify(key) + ': ' + compile(node.properties[key], defs, args));
    }
  }
  return '{' + entries.join(', ') + '}';
}

