def get_header_lines(header):
    """
    Splits the header into lines, putting multi-line headers together.
    """
    import re
    r = []
    lines = header.split(b"\r\n")
    for line in lines:
        if b"\r" in line or b"\n" in line:
            raise ParsingError('Invalid header line')

        # Validate header field names and values according to RFC 7230
        if line and not line.startswith((b" ", b"\t")):
            # This is a header field name line, validate it
            colon_index = line.find(b":")
            if colon_index <= 0:
                raise ParsingError('Invalid header')

            field_name = line[:colon_index]
            field_value = line[colon_index + 1:]

            # Field names should only contain visible ASCII characters (33-126)
            if not re.match(b'^[!-~]+$', field_name):
                raise ParsingError('Invalid header')

            # Validate field values don't contain invalid control characters
            if b'\x0b' in field_value or b'\x0c' in field_value:
                raise ParsingError('Invalid header')

        if line.startswith((b" ", b"\t")):
            if not r:
                # https://corte.si/posts/code/pathod/pythonservers/index.html
                raise ParsingError('Invalid header line')
            # Validate folded header lines don't contain invalid control characters
            if b'\x0b' in line or b'\x0c' in line:
                raise ParsingError('Invalid header')
            r[-1] += line
        else:
            r.append(line)
    return r

