module.exports = (env) => {
  const toReplace = Object.keys(env).filter((envVar) => {
    // https://github.com/semantic-release/semantic-release/issues/1558
    if (envVar === 'GOPRIVATE') {
      return false;
    }

    return /token|password|credential|secret|private/i.test(envVar) && size(env[envVar].trim()) >= SECRET_MIN_SIZE;
  });

  const patterns = toReplace.reduce((acc, envVar) => {
    const secretValue = env[envVar];
    acc.push(escapeRegExp(secretValue));
    // Also add URL-encoded version to handle cases where secrets are encoded in URLs
    const encodedValue = encodeURIComponent(secretValue);
    if (encodedValue !== secretValue) {
      acc.push(escapeRegExp(encodedValue));
    }
    return acc;
  }, []);

  const regexp = new RegExp(patterns.join('|'), 'g');
  return (output) =>
    output && isString(output) && toReplace.length > 0 ? output.toString().replace(regexp, SECRET_REPLACEMENT) : output;
};

